    "ko": "대상 분류로 드래그하세요. 분류 위에 머물면 하위 분류가 표시됩니다. 여러 북마크를 선택해 함께 이동할 수도 있습니다.",
    "es": "Arrastra al destino. Mantén el cursor en una categoría para ver subcategorías o selecciona varios marcadores para moverlos juntos.",
    "fr": "Glissez vers la destination. Survolez une catégorie pour voir ses sous-catégories ou sélectionnez plusieurs favoris à déplacer ensemble.",
    "de": "Ins Ziel ziehen. Kategorie berühren, um Unterkategorien zu sehen, oder mehrere Lesezeichen gemeinsam verschieben.",
    "pt-BR": "Arraste ao destino. Passe sobre uma categoria para ver subcategorias ou selecione vários favoritos para mover juntos.",
    "ru": "Перетащите в категорию назначения. Наведите для показа подкатегорий или выберите несколько закладок для переноса вместе.",
    "it": "Trascina nella destinazione. Passa su una categoria per mostrare le sottocategorie o seleziona più segnalibri da spostare insieme.",
