    "ja": "「パッケージ化されていない拡張機能を読み込む」をクリックし、パッケージ内の",
    "ko": "압축해제된 확장 프로그램 로드를 누르고 패키지의",
    "es": "Pulsa Cargar descomprimida y elige la",
    "fr": "Cliquez sur Charger l’extension non empaquetée et choisissez le",
    "de": "Auf Entpackte Erweiterung laden klicken und den",
    "pt-BR": "Clique em Carregar sem compactação e escolha a",
    "ru": "Нажмите «Загрузить распакованное расширение» и выберите",
